{
    int size_x = strlen(var->map[0]);
    int size_y = 0;

    for (int i = 0; var->map[i] != NULL; i++, size_y++) {
        if (my_strlen(var->map[i]) != size_x)
            return (84);
    }
    var->size_x = size_x - 1;
    var->size_y = size_y - 1;
    return (0);
